// 1. Determine Input and Output paths.
// Prefer the repo-root data/<id>/original.txt layout used by simplify.
// Walk parents from cwd and the executable dir so ./dots works from build/.
const QString relativeInputPath = QString("data/%1/original.txt").arg(id);

auto collectAncestors = [](QDir start, int maxLevels) {
    QStringList roots;
    for (int i = 0; i < maxLevels; ++i) {
        roots.append(start.absolutePath());
        if (!start.cdUp()) break;
    }
    return roots;
};

QStringList searchRoots;
searchRoots += collectAncestors(QDir::current(), 6);
searchRoots += collectAncestors(QDir(QCoreApplication::applicationDirPath()), 6);

QStringList inputCandidates;
QSet<QString> seen;
for (const QString &root : searchRoots) {
    const QString candidate = QDir(root).filePath(relativeInputPath);
    if (seen.contains(candidate)) continue;
    seen.insert(candidate);
    inputCandidates.append(candidate);
}

QString finalInputPath;
for (const QString &candidate : inputCandidates) {
    if (QFile::exists(candidate)) {
        finalInputPath = QFileInfo(candidate).canonicalFilePath();
        break;
    }
}

if (finalInputPath.isEmpty()) {
    qCritical() << "Error: Input file not found. Tried:" << inputCandidates;
    return 1;
}

