function fmtNum(v, digits = 2) {
  if (v == null || Number.isNaN(v)) return "—";
  if (typeof v === "number") return v.toFixed(digits);
  return String(v);
}

function clearCompare() {
  state.compare = null;
  if (resultsBar) resultsBar.hidden = true;
  if (resultChipDots) {
    resultChipDots.hidden = true;
    resultChipDots.classList.remove("on");
    resultChipDots.setAttribute("aria-pressed", "false");
  }
  state.resultVisible.dots = false;
  if (compareMetricsBody) {
    compareMetricsBody.innerHTML =
      '<tr><td colspan="4" class="compare-metrics-empty">Load a trace to compare.</td></tr>';
  }
}

function setResultChip(chip, on) {
  if (!chip) return;
  chip.classList.toggle("on", on);
  chip.setAttribute("aria-pressed", String(on));
}

function renderCompareMetrics() {
  if (!compareMetricsBody) return;
  const t = state.trace;
  const c = state.compare;
  if (!t && !c) {
    compareMetricsBody.innerHTML =
      '<tr><td colspan="4" class="compare-metrics-empty">Load a trace to compare.</td></tr>';
    return;
  }

  const nOrig = c?.metrics?.original_points
    ?? t?.stream?.length
    ?? null;
  const nSimp = t?.simplified?.length
    ?? c?.metrics?.simplify_points
    ?? null;
  const nDots = c?.layers?.dots?.length
    ?? c?.metrics?.dots_points
    ?? null;

  const simpMs = t?.time_ms ?? c?.metrics?.simplify_core_ms ?? null;
  const dotsMs = c?.metrics?.dots_core_ms ?? null;

  const simpFr = state.computedFrechet ?? c?.frechet?.simplify ?? null;
  const dotsFr = c?.frechet?.dots ?? null;
  const frechetLoading = state.computingFrechet
    || (c && c.frechet && c.frechet.dotsLoading);

  const pct = (n, total) =>
    (n != null && total) ? `${((100 * n) / total).toFixed(1)}%` : "—";

  const deltaPts = (nSimp != null && nDots != null) ? (nSimp - nDots) : null;
  const deltaMs = (simpMs != null && dotsMs != null) ? (simpMs - dotsMs) : null;
  const deltaFr = (simpFr != null && dotsFr != null) ? (simpFr - dotsFr) : null;

  const winPtsS = nSimp != null && nDots != null && nSimp < nDots;
  const winPtsD = nSimp != null && nDots != null && nDots < nSimp;
  const winMsS = simpMs != null && dotsMs != null && simpMs < dotsMs;
  const winMsD = simpMs != null && dotsMs != null && dotsMs < simpMs;
  const winFrS = simpFr != null && dotsFr != null && simpFr < dotsFr;
  const winFrD = simpFr != null && dotsFr != null && dotsFr < simpFr;

  const frSimpCell = frechetLoading && simpFr == null
    ? '<span class="button-spinner params-spinner" aria-hidden="true"></span>'
    : fmtNum(simpFr, 4);
  const frDotsCell = (c?.frechet?.dotsLoading && dotsFr == null)
    ? '<span class="button-spinner params-spinner" aria-hidden="true"></span>'
    : fmtNum(dotsFr, 4);

  compareMetricsBody.innerHTML = `
    <tr>
      <td>Simplified points</td>
      <td class="${winPtsS ? "win" : ""}">${nSimp ?? "—"}</td>
      <td class="${winPtsD ? "win" : ""}">${nDots ?? "—"}</td>
      <td>${deltaPts == null ? "—" : (deltaPts > 0 ? "+" : "") + deltaPts}</td>
    </tr>
    <tr>
      <td>Compression</td>
      <td class="${winPtsS ? "win" : ""}">${pct(nSimp, nOrig)}</td>
      <td class="${winPtsD ? "win" : ""}">${pct(nDots, nOrig)}</td>
      <td>—</td>
    </tr>
    <tr>
      <td>Core time (ms)</td>
      <td class="${winMsS ? "win" : ""}">${fmtNum(simpMs, 4)}</td>
      <td class="${winMsD ? "win" : ""}">${fmtNum(dotsMs, 4)}</td>
      <td>${deltaMs == null ? "—" : ((deltaMs > 0 ? "+" : "") + deltaMs.toFixed(4))}</td>
    </tr>
    <tr>
      <td>Frechet vs original</td>
      <td class="${winFrS ? "win" : ""}">${frSimpCell}</td>
      <td class="${winFrD ? "win" : ""}">${frDotsCell}</td>
      <td>${deltaFr == null ? "—" : ((deltaFr > 0 ? "+" : "") + deltaFr.toFixed(4))}</td>
    </tr>
  `;
}

function showResultsBar(hasDots) {
  if (!resultsBar) return;
  resultsBar.hidden = false;
  setResultChip(resultChipOriginal, state.resultVisible.original);
  setResultChip(resultChipSimplify, state.resultVisible.simplify);
  if (resultChipDots) {
    resultChipDots.hidden = !hasDots;
    if (hasDots) {
      state.resultVisible.dots = true;
      setResultChip(resultChipDots, true);
    } else {
      state.resultVisible.dots = false;
      setResultChip(resultChipDots, false);
    }
  }
  renderCompareMetrics();
}

async function loadCompare() {
  clearCompare();
  if (!currentTraceId) {
    // Upload path: still show Results for Original/Simplify; no DOTS file.
    if (state.trace) showResultsBar(false);
    return;
  }
  try {
    const resp = await fetch(`/api/trace/${currentTraceId}/compare?run_dots=1`);
    if (!resp.ok) {
      if (state.trace) showResultsBar(false);
      return;
    }
    const data = await resp.json();
    const layers = data.layers || {};
    if (isSampleTraceId() && layers.dots) {
      layers.dots.forEach((p) => { p[1] += 500; });
    }
    state.compare = {
      layers,
      metrics: data.metrics || {},
      sources: data.sources || {},
      frechet: { simplify: null, dots: null, dotsLoading: false },
    };
    const hasDots = Array.isArray(layers.dots) && layers.dots.length > 0;
    showResultsBar(hasDots);
    if (hasDots) {
      // Frechet for DOTS against original (simplify Frechet still via startFrechetComputation).
      state.compare.frechet.dotsLoading = true;
      renderCompareMetrics();
      fetch(`/api/trace/${currentTraceId}/frechet/dots`)
        .then(async (r) => {
          if (!r.ok) throw new Error(await apiErrorMessage(r));
          return r.json();
        })
        .then((j) => {
          if (!state.compare) return;
          state.compare.frechet.dots = j.distance;
          state.compare.frechet.dotsLoading = false;
          renderCompareMetrics();
        })
        .catch((err) => {
          console.warn("[Compare] DOTS Frechet failed:", err);
          if (!state.compare) return;
          state.compare.frechet.dotsLoading = false;
          renderCompareMetrics();
        });
    }
  } catch (err) {
    console.warn("[Compare] Failed to load compare data:", err);
    if (state.trace) showResultsBar(false);
  }
}

