async function loadCompare() {
  clearCompare();
  if (!currentTraceId) {
    // Upload path: still show Results for Original/Simplify; no DOTS file.
    if (state.trace) showResultsPanel(false);
    return;
  }
  try {
    // Fast path: load any existing polylines first so the Results tab appears
    // immediately (do not block on re-running ./dots).
    let resp = await fetch(`/api/trace/${currentTraceId}/compare`);
    if (!resp.ok) {
      if (state.trace) showResultsPanel(false);
      return;
    }
    let data = await resp.json();
    let layers = data.layers || {};
    if (isSampleTraceId() && layers.dots) {
      layers.dots.forEach((p) => { p[1] += 500; });
    }
    state.compare = {
      layers,
      metrics: data.metrics || {},
      sources: data.sources || {},
      frechet: { simplify: null, dots: null, dotsLoading: false },
      dotsError: data.dots_error || null,
    };
    let hasDots = Array.isArray(layers.dots) && layers.dots.length > 0;
    showResultsPanel(hasDots);

    // Background: run DOTS for timing / generate missing output, then refresh.
    fetch(`/api/trace/${currentTraceId}/compare?run_dots=1`)
      .then(async (r) => (r.ok ? r.json() : null))
      .then((fresh) => {
        if (!fresh || !state.compare) return;
        const freshLayers = fresh.layers || {};
        if (isSampleTraceId() && freshLayers.dots) {
          freshLayers.dots.forEach((p) => { p[1] += 500; });
        }
        state.compare.layers = freshLayers;
        state.compare.metrics = {
          ...(state.compare.metrics || {}),
          ...(fresh.metrics || {}),
        };
        state.compare.sources = fresh.sources || state.compare.sources;
        state.compare.dotsError = fresh.dots_error || null;
        const nowHasDots = Array.isArray(freshLayers.dots) && freshLayers.dots.length > 0;
        if (nowHasDots && !hasDots) {
          hasDots = true;
          showResultsPanel(true);
          startDotsFrechet();
        } else {
          updateResultsOpenBadge(nowHasDots);
          renderCompareMetrics();
          render();
        }
      })
      .catch((err) => console.warn("[Compare] DOTS refresh failed:", err));

    if (hasDots) startDotsFrechet();
  } catch (err) {
    console.warn("[Compare] Failed to load compare data:", err);
    if (state.trace) showResultsPanel(false);
  }
}

function startDotsFrechet() {
  if (!currentTraceId || !state.compare) return;
  state.compare.frechet.dotsLoading = true;
  renderCompareMetrics();
  fetch(`/api/trace/${currentTraceId}/frechet/dots`)
    .then(async (r) => {
      if (!r.ok) throw new Error(await apiErrorMessage(r));
      return r.json();
    })
    .then((j) => {
      if (!state.compare) return;
      state.compare.frechet.dots = j.distance;
      state.compare.frechet.dotsLoading = false;
      renderCompareMetrics();
    })
    .catch((err) => {
      console.warn("[Compare] DOTS Frechet failed:", err);
      if (!state.compare) return;
      state.compare.frechet.dotsLoading = false;
      renderCompareMetrics();
    });
}

function updateResultsOpenBadge(hasDots) {
  const badge = el("resultsPanelOpenBadge");
  if (!badge) return;
  badge.hidden = !hasDots;
  badge.textContent = hasDots ? "DOTS" : "";
}

