@app.route('/api/trace/<int:trace_id>/compare', methods=['GET'])
def get_trace_compare(trace_id):
    """
    GET /api/trace/<id>/compare
    Curves + point counts for the Results strip / metrics table.
    Optional query: run_dots=1 to execute ./build/dots and capture DOTS_CORE_MS.
    """
    trace_dir = DATA_DIR / str(trace_id)
    if not trace_dir.exists() or not (trace_dir / 'original.txt').exists():
        return jsonify({'error': f'Trace {trace_id} not found'}), 404

    run_dots = request.args.get('run_dots', '0') in ('1', 'true', 'yes')
    dots_core_ms = None
    dots_error = None

    if run_dots:
        if not DOTS_BIN.exists():
            dots_error = f'dots binary not found at {DOTS_BIN}'
        else:
            try:
                result = subprocess.run(
                    [str(DOTS_BIN), str(trace_id)],
                    cwd=REPO_ROOT / 'build',
                    capture_output=True,
                    text=True,
                    timeout=120,
                )
                out = (result.stdout or '') + (result.stderr or '')
                m = re.search(r'DOTS_CORE_MS:\s*([\d.]+)', out)
                if m:
                    dots_core_ms = float(m.group(1))
                if result.returncode != 0 and dots_core_ms is None:
                    dots_error = (result.stderr or result.stdout or 'dots failed').strip()
            except Exception as e:
                dots_error = str(e)

    layers, sources = load_trace_layers(trace_id)
    metrics = {
        'original_points': len(layers['original']) if 'original' in layers else None,
        'simplify_points': len(layers['simplify']) if 'simplify' in layers else None,
        'dots_points': len(layers['dots']) if 'dots' in layers else None,
        'dots_core_ms': dots_core_ms,
        'simplify_core_ms': None,  # filled by the live viewer from SIMPLIFY_CORE_MS / trace.time_ms
    }
    return jsonify({
        'trace_id': trace_id,
        'layers': layers,
        'sources': sources,
        'available': sorted(layers.keys()),
        'metrics': metrics,
        'dots_error': dots_error,
    })

