function syncPreloadedTrigger() {
  if (!preloadedTrigger || !preloadedLabel) return;
  const opt = traceSelect.options[traceSelect.selectedIndex];
  const value = traceSelect.value;
  if (!value) {
    preloadedLabel.textContent = "Select trace…";
    preloadedTrigger.classList.remove("has-value");
  } else {
    preloadedLabel.textContent = opt ? opt.textContent : `Trace ${value}`;
    preloadedTrigger.classList.add("has-value");
  }
}

function fitTraceSelectWidth() {
  if (!traceSelect) return;
  // Mobile uses the full-width trigger; only size the desktop native select.
  if (window.matchMedia && window.matchMedia("(max-width: 720px)").matches) {
    traceSelect.style.width = "";
    return;
  }
  const probe = document.createElement("span");
  const cs = getComputedStyle(traceSelect);
  probe.style.cssText = [
    "position:absolute",
    "visibility:hidden",
    "white-space:nowrap",
    "pointer-events:none",
    `font:${cs.font}`,
    `letter-spacing:${cs.letterSpacing}`,
  ].join(";");
  document.body.appendChild(probe);
  let max = 0;
  for (const opt of traceSelect.options) {
    if (opt.disabled) continue;
    probe.textContent = opt.textContent || "";
    max = Math.max(max, probe.offsetWidth);
  }
  probe.remove();
  // Native select needs room for padding + dropdown arrow.
  const width = Math.ceil(max + 28);
  traceSelect.style.width = `${width}px`;
  traceSelect.style.maxWidth = "none";
}

