function baselineAlgoLabel(algo) {
  if (algo === "dots") return "DOTS";
  if (algo === "dp") return "DP";
  if (algo === "squish") return "SQUISH";
  return "Baseline";
}

function baselineLabel() {
  return state.compare?.metrics?.baseline_label
    || baselineAlgoLabel(state.baselineAlgo);
}

function setBaselineStatus(text, kind) {
  if (!baselineStatus) return;
  baselineStatus.textContent = text || "";
  baselineStatus.classList.remove("error", "ok");
  if (kind) baselineStatus.classList.add(kind);
}

function selectedBaselineAlgo() {
  return state.baselineAlgo || "none";
}

function setBaselineAlgo(algo, { clearBaseline = false } = {}) {
  state.baselineAlgo = algo || "none";
  for (const row of baselineAlgoRows()) {
    for (const btn of row.querySelectorAll(".baseline-algo-pill")) {
      const on = btn.dataset.algo === state.baselineAlgo;
      btn.classList.toggle("active", on);
      btn.setAttribute("aria-pressed", String(on));
    }
  }
  syncBaselineParamFields();
  if (clearBaseline || state.baselineAlgo === "none") {
    state.resultVisible.baseline = false;
    if (toggleBaselineCurve) {
      toggleBaselineCurve.checked = false;
      toggleBaselineCurve.disabled = true;
    }
    if (accordionBaselineSummary) accordionBaselineSummary.textContent = "Baseline";
    if (toggleBaselineCurveLabel) toggleBaselineCurveLabel.textContent = "Result curve";
    if (baselineLayerHint) baselineLayerHint.hidden = false;
    if (state.compare) {
      if (state.compare.layers) delete state.compare.layers.baseline;
      if (state.compare.metrics) {
        state.compare.metrics.baseline_points = null;
        state.compare.metrics.baseline_core_ms = null;
        state.compare.metrics.baseline_label = null;
        state.compare.metrics.algorithm = "none";
      }
      renderCompareMetrics();
    }
    if (clearBaseline || state.baselineAlgo === "none") {
      setBaselineStatus(state.baselineAlgo === "none" ? "Baseline cleared." : "");
      render();
    }
  }
}

function syncPairedNumberInputs(a, b, value) {
  const text = String(value);
  if (a && document.activeElement !== a) a.value = text;
  if (b && document.activeElement !== b) b.value = text;
}

function readPairedNumber(a, b, fallback) {
  const raw = (document.activeElement === a && a)
    ? a.value
    : (a?.value ?? b?.value);
  const v = parseFloat(raw);
  return Number.isFinite(v) ? v : fallback;
}

function syncBaselineParamFields() {
  const algo = selectedBaselineAlgo();
  if (baselineLssdField) baselineLssdField.hidden = algo !== "dots";
  if (headerBaselineLssdField) headerBaselineLssdField.hidden = algo !== "dots";
  if (baselineDpEpsField) baselineDpEpsField.hidden = algo !== "dp";
  if (headerBaselineDpEpsField) headerBaselineDpEpsField.hidden = algo !== "dp";
  if (baselineSquishRatioField) baselineSquishRatioField.hidden = algo !== "squish";
  if (headerBaselineSquishRatioField) headerBaselineSquishRatioField.hidden = algo !== "squish";
  syncBaselineLssdInputs();
  syncPairedNumberInputs(baselineDpEpsInput, headerBaselineDpEpsInput, state.baselineDpEps);
  syncPairedNumberInputs(baselineSquishRatioInput, headerBaselineSquishRatioInput, state.baselineSquishRatio);
  if (baselineRunBtn) {
    baselineRunBtn.disabled = !currentTraceId || algo === "none" || baselineRunBtn.dataset.busy === "1";
  }
}

function clearCompare() {
  state.compare = null;
  state.resultVisible.baseline = false;
  closeResultsPanel();
  document.body.classList.remove("results-available");
  if (resultsPanel) resultsPanel.hidden = true;
  if (compareBaselineCol) compareBaselineCol.textContent = "Baseline";
  if (accordionBaselineSummary) accordionBaselineSummary.textContent = "Baseline";
  if (toggleBaselineCurveLabel) toggleBaselineCurveLabel.textContent = "Result curve";
  if (toggleBaselineCurve) {
    toggleBaselineCurve.checked = false;
    toggleBaselineCurve.disabled = true;
  }
  if (baselineLayerHint) baselineLayerHint.hidden = false;
  if (compareFrechetNote) {
    compareFrechetNote.hidden = true;
    compareFrechetNote.textContent = "";
  }
  setBaselineStatus("");
  if (compareMetricsBody) {
    compareMetricsBody.innerHTML =
      '<tr><td colspan="3" class="compare-metrics-empty">Load a trace, then run a baseline.</td></tr>';
  }
  syncBaselineParamFields();
}

function syncLayerTogglesFromState() {
  if (toggles.stream) toggles.stream.checked = !!state.resultVisible.original;
  if (toggleFinalSimplify) toggleFinalSimplify.checked = !!state.resultVisible.simplify;
  if (toggleBaselineCurve) {
    toggleBaselineCurve.checked = !!state.resultVisible.baseline;
  }
}

function renderCompareMetrics() {
  if (!compareMetricsBody) return;
  const t = state.trace;
  const c = state.compare;
  const label = baselineLabel();
  if (compareBaselineCol) compareBaselineCol.textContent = label;

  if (!t && !c) {
    compareMetricsBody.innerHTML =
      '<tr><td colspan="3" class="compare-metrics-empty">Load a trace, then run a baseline.</td></tr>';
    return;
  }

  const nOrig = c?.metrics?.original_points ?? t?.stream?.length ?? null;
  const nSimp = t?.simplified?.length ?? c?.metrics?.simplify_points ?? null;
  const nBase = c?.layers?.baseline?.length
    ?? c?.metrics?.baseline_points
    ?? null;

  const simpMs = t?.time_ms ?? c?.metrics?.simplify_core_ms ?? null;
  const baseMs = c?.metrics?.baseline_core_ms ?? null;
  const simpFr = state.computedFrechet ?? c?.frechet?.simplify ?? null;
  const baseFr = c?.frechet?.baseline ?? null;
  const simpFrLoading = !!state.computingFrechet;
  const baseFrLoading = !!(c && c.frechet && c.frechet.baselineLoading);
  const frechetSpinner =
    '<span class="button-spinner params-spinner" aria-hidden="true"></span>';

  const pct = (n, total) =>
    (n != null && total) ? `${((100 * n) / total).toFixed(1)}%` : "—";

  const winPtsS = nSimp != null && nBase != null && nSimp < nBase;
  const winPtsB = nSimp != null && nBase != null && nBase < nSimp;
  const winMsS = simpMs != null && baseMs != null && simpMs < baseMs;
  const winMsB = simpMs != null && baseMs != null && baseMs < simpMs;
  const winFrS = !simpFrLoading && !baseFrLoading && simpFr != null && baseFr != null && simpFr < baseFr;
  const winFrB = !simpFrLoading && !baseFrLoading && simpFr != null && baseFr != null && baseFr < simpFr;

  const frSimpCell = simpFrLoading ? frechetSpinner : fmtNum(simpFr, 4);
  const frBaseCell = baseFrLoading ? frechetSpinner : fmtNum(baseFr, 4);

  if (compareFrechetNote) {
    if (!baseFrLoading && nBase != null && baseFr != null && Math.abs(baseFr) > 0 && Math.abs(baseFr) < 1e-3) {
      const kept = (nBase != null && nOrig) ? ((100 * nBase) / nOrig).toFixed(1) : "?";
      compareFrechetNote.hidden = false;
      compareFrechetNote.textContent =
        `Baseline Frechet is ${baseFr.toExponential(3)} (not exact zero). ` +
        `With the current parameters the baseline keeps ~${kept}% of points, so discrete Frechet can be tiny.`;
    } else {
      compareFrechetNote.hidden = true;
      compareFrechetNote.textContent = "";
    }
  }

  if (nBase == null) {
    compareMetricsBody.innerHTML = `
    <tr><td>Simplified points</td><td>${nSimp ?? "—"}</td><td>—</td></tr>
    <tr><td>Compression</td><td>${pct(nSimp, nOrig)}</td><td>—</td></tr>
    <tr><td>time (ms)</td><td>${fmtNum(simpMs, 4)}</td><td>—</td></tr>
    <tr><td>Frechet</td><td>${frSimpCell}</td><td>—</td></tr>`;
    return;
  }

  compareMetricsBody.innerHTML = `
    <tr>
      <td>Simplified points</td>
      <td class="${winPtsS ? "win" : ""}">${nSimp ?? "—"}</td>
      <td class="${winPtsB ? "win" : ""}">${nBase ?? "—"}</td>
    </tr>
    <tr>
      <td>Compression</td>
      <td class="${winPtsS ? "win" : ""}">${pct(nSimp, nOrig)}</td>
      <td class="${winPtsB ? "win" : ""}">${pct(nBase, nOrig)}</td>
    </tr>
    <tr>
      <td>time (ms)</td>
      <td class="${winMsS ? "win" : ""}">${fmtNum(simpMs, 4)}</td>
      <td class="${winMsB ? "win" : ""}">${fmtNum(baseMs, 4)}</td>
    </tr>
    <tr>
      <td>Frechet vs original</td>
      <td class="${winFrS ? "win" : ""}">${frSimpCell}</td>
      <td class="${winFrB ? "win" : ""}">${frBaseCell}</td>
    </tr>
  `;
}

function showResultsPanel(hasBaseline) {
  if (!resultsPanel) return;
  resultsPanel.hidden = false;
  document.body.classList.add("results-available");
  closeResultsPanel();

  if (hasBaseline) {
    state.resultVisible.original = false;
    state.resultVisible.simplify = true;
    state.resultVisible.baseline = true;
  }

  const label = baselineLabel();
  if (compareBaselineCol) compareBaselineCol.textContent = label;
  if (accordionBaselineSummary) accordionBaselineSummary.textContent = label;
  if (toggleBaselineCurveLabel) toggleBaselineCurveLabel.textContent = `${label} result`;
  if (toggleBaselineCurve) {
    toggleBaselineCurve.disabled = !hasBaseline;
    toggleBaselineCurve.checked = hasBaseline && state.resultVisible.baseline;
  }
  if (baselineLayerHint) baselineLayerHint.hidden = hasBaseline;
  // Keep the baseline accordion collapsed by default.
  if (accordionBaseline) accordionBaseline.open = false;

  syncLayerTogglesFromState();
  syncBaselineParamFields();
  renderCompareMetrics();
}

function applyComparePayload(data) {
  const layers = { ...(data.layers || {}) };
  const algo = data.algorithm || data.metrics?.algorithm || selectedBaselineAlgo();
  if (!layers.baseline && algo && algo !== "none" && layers[algo]) {
    layers.baseline = layers[algo];
  }
  if (isSampleTraceId() && layers.baseline) {
    layers.baseline.forEach((p) => { p[1] += 500; });
  }
  state.compare = {
    layers,
    metrics: data.metrics || {},
    sources: data.sources || {},
    frechet: state.compare?.frechet || { simplify: null, baseline: null, baselineLoading: false },
    baselineError: data.baseline_error || data.dots_error || null,
  };
  return Array.isArray(layers.baseline) && layers.baseline.length > 0;
}

async function loadCompare() {
  clearCompare();
  if (!currentTraceId) {
    if (state.trace) showResultsPanel(false);
    return;
  }
  try {
    const resp = await fetch(`/api/trace/${currentTraceId}/compare?algorithm=none`);
    if (!resp.ok) {
      if (state.trace) showResultsPanel(false);
      return;
    }
    const data = await resp.json();
    applyComparePayload(data);
    showResultsPanel(false);
    const algo = selectedBaselineAlgo();
    if (algo !== "none") {
      setBaselineStatus(`Running selected baseline (${baselineAlgoLabel(algo)})…`);
      await runSelectedBaseline();
    } else {
      setBaselineStatus("Choose a baseline algorithm and click Run.");
    }
  } catch (err) {
    console.warn("[Compare] Failed to load compare shell:", err);
    if (state.trace) showResultsPanel(false);
  }
}

async function runSelectedBaseline() {
  if (!currentTraceId) {
    setBaselineStatus("Load a preloaded trace first.", "error");
    return;
  }
  const algo = selectedBaselineAlgo();
  if (algo === "none") {
    setBaselineStatus("Select a baseline algorithm first.", "error");
    return;
  }
  let lssd = state.baselineLssd;
  let dpEps = state.baselineDpEps;
  let squishRatio = state.baselineSquishRatio;
  if (algo === "dots") {
    lssd = readBaselineLssdFromInputs();
    if (!Number.isFinite(lssd) || lssd <= 0) {
      setBaselineStatus("LSSD must be a positive number.", "error");
      return;
    }
  } else if (algo === "dp") {
    dpEps = readPairedNumber(baselineDpEpsInput, headerBaselineDpEpsInput, state.baselineDpEps);
    if (!Number.isFinite(dpEps) || dpEps <= 0) {
      setBaselineStatus("DP PED ε must be a positive number.", "error");
      return;
    }
    state.baselineDpEps = dpEps;
    syncPairedNumberInputs(baselineDpEpsInput, headerBaselineDpEpsInput, dpEps);
  } else if (algo === "squish") {
    squishRatio = readPairedNumber(baselineSquishRatioInput, headerBaselineSquishRatioInput, state.baselineSquishRatio);
    if (!Number.isFinite(squishRatio) || squishRatio <= 0 || squishRatio > 1) {
      setBaselineStatus("SQUISH ratio must be in (0, 1].", "error");
      return;
    }
    state.baselineSquishRatio = squishRatio;
    syncPairedNumberInputs(baselineSquishRatioInput, headerBaselineSquishRatioInput, squishRatio);
  }

  if (baselineRunBtn) {
    baselineRunBtn.dataset.busy = "1";
    baselineRunBtn.disabled = true;
    baselineRunBtn.textContent = "Running…";
  }
  setBaselineStatus(`Running ${baselineAlgoLabel(algo)}…`);

  try {
    const qs = new URLSearchParams({ algorithm: algo, run: "1" });
    if (algo === "dots") qs.set("lssd", String(lssd));
    if (algo === "dp") qs.set("epsilon", String(dpEps));
    if (algo === "squish") qs.set("ratio", String(squishRatio));
    const resp = await fetch(`/api/trace/${currentTraceId}/compare?${qs.toString()}`);
    if (!resp.ok) throw new Error(await apiErrorMessage(resp));
    const data = await resp.json();
    if (data.baseline_error || data.dots_error) {
      setBaselineStatus(data.baseline_error || data.dots_error, "error");
    } else {
      const label = data.metrics?.baseline_label || baselineAlgoLabel(algo);
      const n = data.metrics?.baseline_points;
      setBaselineStatus(n != null ? `${label} ready (${n} points).` : `${label} ready.`, "ok");
    }
    const hasBaseline = applyComparePayload(data);
    showResultsPanel(hasBaseline);
    if (hasBaseline) {
      openResultsPanel();
      startBaselineFrechet();
      render();
    }
  } catch (err) {
    console.warn("[Compare] Baseline run failed:", err);
    setBaselineStatus(err.message || "Baseline run failed", "error");
  } finally {
    if (baselineRunBtn) {
      baselineRunBtn.dataset.busy = "0";
      baselineRunBtn.textContent = "Run baseline";
      syncBaselineParamFields();
    }
  }
}

function startBaselineFrechet() {
  if (!currentTraceId || !state.compare?.layers?.baseline) return;
  state.compare.frechet = state.compare.frechet || {};
  state.compare.frechet.baselineLoading = true;
  state.compare.frechet.baseline = null;
  if ("dots" in state.compare.frechet) state.compare.frechet.dots = null;
  renderCompareMetrics();
  fetch(`/api/trace/${currentTraceId}/frechet/${encodeURIComponent(selectedBaselineAlgo())}`)
    .then(async (r) => {
      if (!r.ok) throw new Error(await apiErrorMessage(r));
      return r.json();
    })
    .then((j) => {
      if (!state.compare) return;
      state.compare.frechet.baseline = j.distance;
      state.compare.frechet.baselineLoading = false;
      renderCompareMetrics();
    })
    .catch((err) => {
      console.warn("[Compare] Baseline Frechet failed:", err);
      if (!state.compare) return;
      state.compare.frechet.baselineLoading = false;
      renderCompareMetrics();
    });
}

